const unprocessedMpesaCallbacks = `-- name: UnprocessedMpesaCallbacks :many
SELECT id FROM mpesa_callbacks
WHERE processed_at IS NULL AND verdict = 'matched' AND created_at < now() - interval '1 minute'
ORDER BY created_at LIMIT 100
`

// Matched callbacks that were stored but not processed (the inline attempt
// failed). Older than a minute, so an inline attempt still running is left alone.
func (q *Queries) UnprocessedMpesaCallbacks(ctx context.Context) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, unprocessedMpesaCallbacks)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
